import{_ as i,o as a,c as t,a3 as e}from"./chunks/framework.DeRSg1wr.js";const g=JSON.parse('{"title":"Log4j2框架适配器","description":"Log4j2 的 MDC 和 TLog 消息插件配置，说明异步事件快照。","frontmatter":{"title":"Log4j2框架适配器","date":"2022-09-12T13:45:24.000Z","permalink":"/pages/8d5538/","description":"Log4j2 的 MDC 和 TLog 消息插件配置，说明异步事件快照。"},"headers":[],"relativePath":"pages/8d5538/index.md","filePath":"10.文档/070.日志框架适配方式/040.Log4j2框架适配器.md"}'),n={name:"pages/8d5538/index.md"};function l(h,s,p,k,d,E){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="log4j2框架适配器" tabindex="-1">Log4j2框架适配器 <a class="header-anchor" href="#log4j2框架适配器" aria-label="Permalink to &quot;Log4j2框架适配器&quot;">​</a></h1><p>Log4j2 可以使用 MDC 输出，也保留 TLog 的消息插件。应用应提供与自己 SLF4J 版本匹配的 binding，避免同时加载 logback 和 Log4j2 两套实现。</p><h2 id="mdc-输出" tabindex="-1">MDC 输出 <a class="header-anchor" href="#mdc-输出" aria-label="Permalink to &quot;MDC 输出&quot;">​</a></h2><p>设置 <code>tlog.mdc-enable=true</code>，使用应用原有的 <code>PatternLayout</code>：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Configuration</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;WARN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Appenders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Console</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CONSOLE&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SYSTEM_OUT&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">PatternLayout</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pattern</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%d{HH:mm:ss.SSS} %-5level [%thread] %X{tl} %msg%n&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Console</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Appenders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Loggers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Root</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;info&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">AppenderRef</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CONSOLE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Root</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Loggers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Configuration</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><code>tl</code> 是完整标签；<code>%X{tlogTraceId}</code> 和 <code>%X{tlogSpanId}</code> 可分别输出两个字段。</p><p>这里必须设置 <code>tlog.mdc-enable=true</code>。TLog 的 Log4j2 插件也注册了 <code>%m</code>/<code>%msg</code>，如果它被 Log4j2 选中、又没开启这个开关，消息前会再拼接一份标签。</p><h2 id="保留消息前缀插件" tabindex="-1">保留消息前缀插件 <a class="header-anchor" href="#保留消息前缀插件" aria-label="Permalink to &quot;保留消息前缀插件&quot;">​</a></h2><p>已有项目可使用 TLog 插件的明确别名 <code>%tm</code>、<code>%tmsg</code> 或 <code>%tmessage</code>，例如：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">PatternLayout</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pattern</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%d{HH:mm:ss.SSS} %-5level [%thread] %logger{36} - %tmsg%n&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span></code></pre></div><p>这种写法将标签放在消息前，应保持 <code>tlog.mdc-enable</code> 未启用，并且不要再重复输出 <code>%X{tl}</code>。不要依靠 Maven 依赖顺序去覆盖原生 <code>%m</code>/<code>%msg</code> 的插件选择。</p><p>打包时要保留 TLog jar 的 Log4j2 插件元数据。自行制作 shaded jar 时，应按日志框架的要求合并插件资源；出现无法识别 <code>%tmsg</code> 时先检查插件发现和日志启动状态。</p><h2 id="异步-appender" tabindex="-1">异步 appender <a class="header-anchor" href="#异步-appender" aria-label="Permalink to &quot;异步 appender&quot;">​</a></h2><p>MDC 字段在业务线程创建日志事件时保存。普通 Log4j2 Async appender 可以输出这个快照：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Async</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ASYNC&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">AppenderRef</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CONSOLE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Async</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>将 <code>ASYNC</code> 放入 <code>Appenders</code>，并让 Root 引用它。队列和 AsyncLogger 所需的其它依赖按应用自身的 Log4j2 配置管理。</p><p>不需要为了这个异步 appender 示例设置 <code>log4j2.isThreadContextMapInheritable=true</code>。线程创建时的继承也不能代替线程池按任务传播；业务异步使用<a href="/pages/a69e1d/">自动装饰或 TLogExecutors</a>。</p>`,17)])])}const r=i(n,[["render",l]]);export{g as __pageData,r as default};
